      "शाळेत विद्यार्थी वस्तूची लांबी कशाने मोजतात ते सांगतो. त्याचे प्रयत्न कौतुकास्पद आहेत.",
      "आमच्या निरीक्षणात विद्यार्थी वेळ पाहण्यासाठी घड्याळ वापरतो. त्याच्या या कामगिरीबद्दल अभिनंदन.",
      "निरीक्षणानुसार विद्यार्थी वर्गात भिंग वापरून लहान वस्तू पाहतो. त्याला नियमित प्रोत्साहन देणे फायदेशीर ठरेल.",
      "सरावात विद्यार्थी मोबाईल कधी वापरावा याची समज दाखवतो. ही सवय पुढेही टिकवावी.",
